SELECT DATE_FORMAT(paid_at, 'yyyy-MM') AS paid_month, CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, CASE WHEN amount >= 1440 THEN 'high' WHEN amount >= 730 THEN 'mid' ELSE 'low' END AS amount_bucket, MIN(paid_at) AS min_paid_at, COUNT(amount) AS amount_count FROM payments WHERE order_id = 31 AND method = 'card' GROUP BY 1, 2, 3;
